// 50 test inputs for the Claude order extraction pipeline.
//
// 40 realistic messy order messages, Indonesian and English mixed, typos
// left in on purpose. 10 adversarial inputs at the end.
//
// Consumed two ways: required by tooling, and inlined into the n8n
// "Test Fixtures" Code node by the build script, which swaps the export
// line at the bottom for a return statement.
//
// Running all 50 costs at least 50 Claude calls, plus one extra for every
// input that fails validation on the first pass.

const fixtures = [

  // ---------- Amount formats ----------
