    raw_text: 'Hi, I want the bundle: 1 Jacket size large + 2 T-Shirts size M + 1 Cap. Name Kevin Wijaya, address Jl. Asia Afrika No. 100, Bandung 40261. Phone 081822334455, email kevin.wijaya@example.test. Bundle price Rp 899.000.'
  },

  // ---------- Register and formatting variety ----------

  {
    fixture_id: 'f24-whatsapp-lowercase',
    raw_text: 'kak mau order dong 2 kaos size l warna navy sama 1 celana pendek size 30 kirim ke jl kenari no 8 jakarta timur 13120 an sari dewi hp 081911223344 email saridewi@gmail com total 385rb ya makasih'
