//     into the Orders database, every one of them with an empty
//     amount_as_written and a total of exactly the lower bound. An empty
//     input string became an order for one unit of "<UNKNOWN>".
//
//     amount_as_written is the verbatim evidence for total_amount_idr. With
//     no evidence there is no amount, so any total at all is invented, and
//     an invented total is exactly what this pipeline exists to refuse.
//     This is structural: it holds no matter how the model is prompted, and
//     it is the layer that actually stopped the leak. The reworded B1
//     message only removes the temptation.
if (isBlank(data.amount_as_written)) {
  errors.push('B8: amount_as_written is empty, so total_amount_idr ' +
    JSON.stringify(total) + ' has no source in the customer text');
}

return finish();

// Shapes a validated extraction into the fields the Notion "Orders" node
// writes. Reached from both IF nodes: attempt 1 passing, or the retry
// passing.
//
// This runs AFTER validation, so it is formatting for storage, not repair.
// D1 is untouched: no value is corrected here, only cut to fit Notion's
// limits, and whatever is cut is recorded as a length instead of vanishing.
const src = $json ?? {};
const d = src.data ?? {};
const m = src.metrics ?? {};

// A Notion rich_text property holds at most 2000 characters.
const LIMIT = 1900;
const cut = s => (s.length > LIMIT ? s.slice(0, LIMIT) + '... [truncated]' : s);
const str = v => (typeof v === 'string' ? v : '');

// Notion rejects "" for email, phone_number and select properties: those
// accept a real value or null, nothing in between. rich_text and number are
// happy with "" and null respectively, so only these three need the guard.
const orNull = s => (s === '' ? null : s);

const rawText = str(src.raw_text);
const items = Array.isArray(d.items) ? d.items : [];

return {
  json: {
    // Notion needs a title on every page. An order can legitimately have no
    // customer name, so fall back to something a human can still recognise.
    notion_title: str(d.customer_name).trim() ||
      ('Order without a name (' + (str(src.fixture_id) || 'webhook') + ')'),
    customer_email: orNull(str(d.customer_email)),
    customer_phone: orNull(str(d.customer_phone)),
    shipping_address: cut(str(d.shipping_address)),
    items_json: cut(JSON.stringify(items)),
    item_count: items.length,
    total_amount_idr: d.total_amount_idr,
    amount_as_written: str(d.amount_as_written),
    needs_review: d.needs_review === true,
    review_reason: cut(str(d.review_reason)),
    attempts_used: m.attempt_count ?? src.attempt_count ?? null,
    stop_reason: orNull(str(m.stop_reason)),
    input_tokens: m.input_tokens ?? null,
    output_tokens: m.output_tokens ?? null,
    elapsed_ms: m.elapsed_ms ?? null,
    raw_text: cut(rawText),
    raw_text_length: rawText.length,
    fixture_id: str(src.fixture_id)
  }
};

// Shapes a twice-failed extraction into the fields the Notion "Order DLQ"
// node writes, and composes the Slack alert text alongside it.
//
// The Slack node sits after the Notion node, and a Notion node replaces the
// item json with its own API response, so the Slack node reads its message
// back from this node by name rather than from $json.
const src = $json ?? {};
const d = src.data;
const m = src.metrics ?? {};

const LIMIT = 1900;
const cut = s => (s.length > LIMIT ? s.slice(0, LIMIT) + '... [truncated]' : s);
const str = v => (typeof v === 'string' ? v : '');

// Notion rejects "" for select properties. Stop Reason is genuinely absent
// whenever the API call failed before Claude produced a stop reason, so it
// has to go across as null rather than as an empty string.
const orNull = s => (s === '' ? null : s);

const errors2 = Array.isArray(src.errors) ? src.errors : [];
const errors1 = Array.isArray(src.first_attempt_errors) ? src.first_attempt_errors : [];
const rawText = str(src.raw_text);

// Every validation message starts with its rule code, so the first two
// characters are the code. Anything that does not look like one is dropped
// rather than written to Notion as a junk tag.
// Written out rather than as a [1-9] range: adding a rule means adding it
// here AND as an option on the Notion "Rule Codes" property, and an
// explicit list makes the second step impossible to forget. B8 was
// silently swallowed by an earlier [1-7] pattern.
const KNOWN_RULES = ['S1', 'S2', 'S3', 'S4', 'S5',
                     'B1', 'B2', 'B3', 'B4', 'B5', 'B6', 'B7', 'B8'];
const ruleCodes = Array.from(new Set(errors2.map(e => String(e).slice(0, 2))))
  .filter(c => KNOWN_RULES.includes(c));

const snippet = rawText.replace(/\s+/g, ' ').trim().slice(0, 80);
const summary = (ruleCodes.join(' ') || 'no rule code') +
  ' - ' + (snippet || '(empty input)');

const slack_text = [
  ':rotating_light: *Order extraction quarantined*',
  '',
  '*Failed rules:* ' + (ruleCodes.join(', ') || 'none parsed'),
  '*Source:* ' + (str(src.fixture_id) || 'webhook'),
  '*Attempts:* ' + (m.attempt_count ?? 2),
  '',
  '*Errors on the second attempt:*',
  errors2.length ? errors2.map(e => '- ' + e).join('\n') : '- (none recorded)',
  '',
  '*Customer text:*',
  '```' + (rawText.slice(0, 600) || '(empty)') + '```'
].join('\n');

return {
  json: {
    notion_title: cut(summary),
    status: 'New',
    rule_codes: ruleCodes,
    errors_2: cut(errors2.join('\n')),
    errors_1: cut(errors1.join('\n')),
    extracted_data: cut(d === null || d === undefined ? '(no tool_use block)' : JSON.stringify(d, null, 2)),
    api_error: cut(str(src.api_error)),
    stop_reason: orNull(str(m.stop_reason)),
    attempts_used: m.attempt_count ?? 2,
    input_tokens: m.input_tokens ?? null,
    output_tokens: m.output_tokens ?? null,
    elapsed_ms: m.elapsed_ms ?? null,
    raw_text: cut(rawText),
    raw_text_length: rawText.length,
    fixture_id: str(src.fixture_id),
    slack_text
  }
};
